// GD_EDIT_WORKER - Guard: optional job_id (digits: this job only), session tenant, this run's lease owner WRK|<nonce>.
// Kicked by the GD form after a submit, by its mounted view and the GD list (no Quartz): drains up to 5 due EDIT_GD jobs.
// Ownership of a job = the CLAIM GATE (unique gd_publish_step W0_CLAIM_<row_version>); the lease is the liveness timer.
const workerGuard = function workerGuard(input) {
  const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
