  if (!/^[0-9]{1,20}$/.test(tenantId)) return bad("no session tenant");
  return { route: "CONTINUE", jobId: jobId, tenantId: tenantId, nonce: nonce, leaseOwner: "WRK|" + nonce, result_code: "", result_message: "" };
};
