  return { worker_route: guard.route === "REJECT" ? "REJECTED" : !plan || plan.route === "IDLE" ? "IDLE" : "WORKED", processed: String(jobs.length), jobs: JSON.stringify(jobs), job_id: first ? first.job_id : "", job_status: first ? first.job_status : "", result_code: firstRow && s(firstRow.error_code) ? s(firstRow.error_code) : s(guard.result_code), result_message: firstRow && s(firstRow.error_message) ? s(firstRow.error_message) : s(guard.result_message) || s(plan && plan.result_message), gd_id: first ? first.gd_id : "", evidence: JSON.stringify({ v: 1, workflow: "GD_EDIT_WORKER", path: "REJECTED_INPUT" }) };
};
